import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
L=np.log(P); s=np.sqrt(P)
A={'1/P':1/P,'1':np.ones_like(P),'s':s,'P':P,'P2':P**2,'P3':P**3,'L':L,'PL':P*L}
Tt={'1':np.ones_like(P),'s':s,'P':P,'P2':P**2,'1/P':1/P,'L':L}
